INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱全忠约杨行密共攻孙儒", "start_year": 891, "end_year": 891, "time_original": "891年七月后条；具体日未载", "dynasty": "唐", "description": "朱全忠遣使与杨行密约共攻孙儒。孙儒欲先灭杨行密、后敌朱全忠，向藩镇移牒指责二人，声称平宣汴后将入朝除君侧之恶。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "20d178c9-e65b-5e01-81f8-17dc82e2d158"}, {"title": "孙儒焚扬州，驱民渡江杀老弱", "start_year": 891, "end_year": 891, "time_original": "891年七月后条；具体日未载", "dynasty": "唐", "description": "孙儒焚尽扬州庐舍，驱丁壮与妇女渡江，并杀老弱以充食。", "phases": [], "location_name": "扬州、江", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "262186b3-0c6f-56ea-a61e-54b2d53cbc64"}, {"title": "张训李德诚入扬州灭火发谷赈饥", "start_year": 891, "end_year": 891, "time_original": "891年七月后条；孙儒焚扬州后", "dynasty": "唐", "description": "杨行密将张训、李德诚潜入扬州，灭余火，获得谷数十万斛以赈饥民。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a5059f4b-e71d-5606-9e1e-1de6aafaed4c"}, {"title": "张谏借谷给军，张训奉命馈还", "start_year": 891, "end_year": 891, "time_original": "891年七月后条；具体日未载", "dynasty": "唐", "description": "泗州刺史张谏借数万斛谷给军，张训奉杨行密之命馈给张谏，张谏由此感德杨行密。", "phases": [], "location_name": "泗州、扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "23d573d9-6f11-56d9-a1ec-e90352a5bf52"}, {"title": "李存孝劝李克用攻镇州", "start_year": 891, "end_year": 891, "time_original": "891年七月后条；八月南巡前", "dynasty": "唐", "description": "邢洺节度使李存孝劝李克用攻镇州，李克用采纳。", "phases": [], "location_name": "镇州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c56a9af0-bea2-536a-8be1-5c46954f9cc1"}, {"title": "李克用八月巡泽潞涉怀孟", "start_year": 891, "end_year": 891, "time_original": "891年八月", "dynasty": "唐", "description": "李克用南巡泽潞，进入怀孟境内。", "phases": [], "location_name": "泽潞、怀孟", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6a507edb-4e4b-5689-9eac-0d36192ab352"}, {"title": "丁会攻克宿州外城", "start_year": 891, "end_year": 891, "time_original": "891年八月条；具体日未载", "dynasty": "唐", "description": "朱全忠遣丁会攻宿州，克其外城。", "phases": [], "location_name": "宿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "15b8d150-aad9-51a7-9793-9a324076c542"}, {"title": "李简广德力战救出杨行密", "start_year": 891, "end_year": 891, "time_original": "891年八月乙未", "dynasty": "唐", "description": "孙儒由苏州出屯广德，杨行密率军抵抗而营寨被围。上蔡李简率百余人力战破围，救出杨行密。", "phases": [], "location_name": "苏州、广德", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a94cf18c-fa10-5cce-b5ee-2f15b42d6aea"}, {"title": "王建占新都断陈敬瑄彭州粮道", "start_year": 891, "end_year": 891, "time_original": "891年八月条；成都受降前", "dynasty": "唐", "description": "王建加紧攻陈敬瑄，陈出战多败、所辖州县多被取。威戎节度使杨晟时常送粮，王建以兵据新都，使彭州道路断绝；陈敬瑄慰勉士卒无人回应。", "phases": [], "location_name": "成都、新都、彭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2718eee3-ab9b-5dee-9969-9015608b60c1"}, {"title": "田令孜携西川印节授王建", "start_year": 891, "end_year": 891, "time_original": "891年八月辛丑夜", "dynasty": "唐", "description": "田令孜登城与王建对话，王建称未忘父子恩但奉朝廷命讨不受代者。当夜田令孜携西川印节至王建营授之，王建谢并请恢复父子关系如初。", "phases": [], "location_name": "成都城、王建营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fd216c52-158d-5059-a3fc-a9ff566ca360"}, {"title": "王建围城前许将士取财轮任节度使", "start_year": null, "end_year": null, "time_original": "先是；成都受降前，确年日未载", "dynasty": "唐", "description": "《通鉴》追述王建曾许将士得成都后恣取金帛子女，并轮日任节度使。", "phases": [], "location_name": "成都城外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dd75fd6a-4dd8-5565-b152-5eef9a2a0ec8"}, {"title": "陈敬瑄开城，张勍先入禁止焚掠", "start_year": 891, "end_year": 891, "time_original": "891年八月壬寅及其后", "dynasty": "唐", "description": "陈敬瑄开城迎王建，王建任张勍为马步斩斫使使先入，告诫将士不得焚掠坊市。张勍捕百余犯令士卒，捶胸杀之，众遂不敢犯，时人称张打胸。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f8b364ba-18d1-58c5-b1e5-1960343f5ebe"}, {"title": "王建入成都自称西川留后", "start_year": 891, "end_year": 891, "time_original": "891年八月癸卯", "dynasty": "唐", "description": "王建进入成都，自称西川留后。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6790cb5d-a249-5a85-89da-5624986ecaf9"}, {"title": "韩武引轮任许诺抗议，被王建刺杀", "start_year": 891, "end_year": 891, "time_original": "891年八月癸卯后条；具体日未载", "dynasty": "唐", "description": "小校韩武屡在使厅上马，牙司阻止，韩武以王建曾许轮任节度使反驳，王建暗遣人刺杀韩武。", "phases": [], "location_name": "成都使厅", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "43dd123f-e180-5a7b-8314-57b8d3e4d010"}, {"title": "田令孜取得陈敬瑄军政的追叙", "start_year": null, "end_year": null, "time_original": "初；陈敬瑄拒朝命时，确年日未载", "dynasty": "唐", "description": "《通鉴》追述陈敬瑄拒朝命时，田令孜建议代掌军务、每日咨呈，陈敬瑄同意，此后军政不由己。", "phases": [], "location_name": "西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "109ac845-42e7-57bc-b766-d23be471fbfd"}, {"title": "王建表陈陶为雅州刺史，陈敬瑄随行", "start_year": 891, "end_year": 891, "time_original": "891年成都平后；具体日未载", "dynasty": "唐", "description": "王建上表请陈敬瑄之子陈陶为雅州刺史，使陈敬瑄随陈陶赴任。", "phases": [], "location_name": "雅州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6eea65e9-b2de-5315-9885-cb1e0d084aec"}, {"title": "陈敬瑄次年罢归，寓居新津", "start_year": 892, "end_year": 892, "time_original": "明年；892年，具体日未载", "dynasty": "唐", "description": "《通鉴》在成都平后段预叙次年陈敬瑄罢归、寓居新津，王建以一县租赋赡养。", "phases": [], "location_name": "新津", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5292a2a9-9161-56f5-ab2d-4f947e271681"}, {"title": "王建分军就食诸州，改文武坚谢从本姓名", "start_year": 891, "end_year": 891, "time_original": "891年八月癸丑", "dynasty": "唐", "description": "王建分遣士卒到诸州就食，将文武坚、谢从本分别更名。底本记王完阮、王宗本；胡注本与《十国春秋》文武坚传记前者为王宗阮。陈敬瑄将佐中有才干者，王建礼待任用。", "phases": [], "location_name": "西川诸州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "38c6f4a7-555a-585c-8655-99c786bda8e9"}, {"title": "杨复恭专掌禁兵，假子牧守拒贡", "start_year": null, "end_year": null, "time_original": "九月致仕前的背景；确年日未载", "dynasty": "唐", "description": "《通鉴》述杨复恭总宿卫兵、专制朝政，诸假子任节度使刺史，另养宦官子六百人任监军。龙剑节度使杨守贞、武定节度使杨守忠不输贡赋并上表讥薄朝廷；胡注本相同位置记守思。", "phases": [], "location_name": "京师、龙剑、武定", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1d701d53-6c9c-58a1-a474-bcabea23063c"}, {"title": "皇舅王瑰求节度，与杨复恭争执后外任", "start_year": null, "end_year": null, "time_original": "九月杨复恭致仕前；确年日未载", "dynasty": "唐", "description": "皇舅瑰求节度使，皇帝询杨复恭而被否，瑰怒斥之。其出入禁中任事，杨复恭厌恶，上奏任其黔南节度使；《旧唐书》此人记王瑰，胡注本记王瓌。", "phases": [], "location_name": "禁中、黔南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "11731efb-fb16-5f2b-84e5-89049cd532e0"}, {"title": "王瑰吉柏津覆舟死亡，两书记述不同", "start_year": null, "end_year": null, "time_original": "九月杨复恭致仕前；确年日未载", "dynasty": "唐", "description": "《通鉴》记杨复恭令杨守亮将皇舅瑰覆于江中，宗族宾客皆死，按船毁上报，皇帝深恨；《旧唐书》只记覆舟而没及舆论归咎杨复恭，责任说法并列保留。", "phases": [], "location_name": "吉柏津", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5fb4c9e5-142e-5f3f-8f7f-3528ab1597c3"}, {"title": "李顺节告杨复恭阴事，复恭拒赴凤翔", "start_year": 891, "end_year": 891, "time_original": "九月乙卯致仕前；具体日未载", "dynasty": "唐", "description": "李顺节与杨复恭争权，将复恭隐事尽告皇帝；朝廷出复恭为凤翔监军，复恭愠怒不肯前往，称病求致仕。", "phases": [], "location_name": "京师、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dfe1742a-821b-57c5-b62f-cce2e3df04dd"}, {"title": "杨复恭致仕后遣张绾杀使者", "start_year": 891, "end_year": 891, "time_original": "891年九月乙卯及其后", "dynasty": "唐", "description": "朝廷以杨复恭为上将军致仕，赐几杖。使者送诏后返，杨复恭暗遣腹心张绾刺杀使者。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "57bfac7e-c47b-5e7a-816a-07e086cda250"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "假父", "description": "《通鉴》卷256记田令孜在十一月收王建为假子。", "status": "draft", "id": "5489bb20-ce00-5f73-9c7e-0d770a289e94", "person_a": "5080b636-4944-5887-afed-2195aeb4a567", "person_b": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"relation_type": "父亲", "description": "《通鉴》称陈陶为陈敬瑄之子；陈敬瑄是陈陶的父亲。", "status": "draft", "id": "984b1a09-02f1-59ed-b2c8-a7d92d01b0cf", "person_a": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71", "person_b": "1008355c-af16-5fef-99b7-096377f23683"}, {"relation_type": "养父", "description": "《十国春秋》记成都平后王建养谢从本为子并改名王宗本；王建是谢从本的养父。", "status": "draft", "id": "4358544a-663c-528c-8962-b858704c2b88", "person_a": "b02193d6-1c17-5154-bb7c-3295ed8dbbec", "person_b": "7980becb-be69-53a7-b1f4-2a6acf83646b"}, {"relation_type": "假父", "description": "《通鉴》本电子底本记杨守贞为杨复恭假子；杨复恭是假父。", "status": "draft", "id": "eb914f51-f200-5981-99ae-a92471e90ca3", "person_a": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51", "person_b": "20b5a758-b788-5956-b09f-d976b8538b1e"}, {"relation_type": "假父", "description": "《通鉴》本电子底本记杨守忠为杨复恭假子；杨复恭是假父。武定节度使名另本作守思，身份记名尚待校核。", "status": "draft", "id": "8d032b04-4769-576b-89b1-fb30f41bcf6e", "person_a": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51", "person_b": "50f2860b-439a-50ba-9bde-3a2cd10515bc"}, {"relation_type": "舅父", "description": "《通鉴》称瑰为皇帝舅，《旧唐书》记国舅王瑰；王瑰是唐昭宗李杰的舅父。", "status": "draft", "id": "8a663a96-0263-5d42-8bf9-9538eaf111b3", "person_a": "3166a2ac-ae99-55e8-b83f-8d7f0704fb38", "person_b": "48935190-c754-5bda-bdcd-382c77cb2de0"}]'::jsonb)
