SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "朱全忠遣使与杨行密约共攻孙儒。孙儒欲先灭杨行密、后敌朱全忠，向藩镇移牒指责二人，声称平宣汴后将入朝除君侧之恶。", "citation": "卷258·大顺二年（891）·zztj-v258-y0891-p017·原文件第93行", "note": "原文：硃全忠遣使与杨行密约共攻孙儒。儒恃其兵强，欲先灭行密，后敌全忠，移牒籓镇，数行密、全忠之罪，且曰：“俟平宣、汴，当引兵入朝，除君侧之恶。”于是悉焚扬州庐舍，尽驱丁壮及妇女渡江，杀老弱以充食。行密将张训、李德诚潜入扬州，灭馀火，得谷数十万斛以赈饥民。泗州刺史张谏贷数万斛以给军，训以行密之命馈之，谏由是德行密。；核对说明：约攻是本次军议；孙儒计划与移牒声称不当作已执行，不记终身同盟。", "status": "draft", "id": "1d6bfcfe-0fba-5916-9d19-1149d392f35f", "subject_id": "20d178c9-e65b-5e01-81f8-17dc82e2d158", "source_id": "d3357220-e689-5ebf-b1a9-6ec7b921c7de"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "891年七月后条；具体日未载", "citation": "卷258·大顺二年（891）·zztj-v258-y0891-p017·原文件第93行", "note": "原文：硃全忠遣使与杨行密约共攻孙儒。儒恃其兵强，欲先灭行密，后敌全忠，移牒籓镇，数行密、全忠之罪，且曰：“俟平宣、汴，当引兵入朝，除君侧之恶。”于是悉焚扬州庐舍，尽驱丁壮及妇女渡江，杀老弱以充食。行密将张训、李德诚潜入扬州，灭馀火，得谷数十万斛以赈饥民。泗州刺史张谏贷数万斛以给军，训以行密之命馈之，谏由是德行密。；核对说明：约攻是本次军议；孙儒计划与移牒声称不当作已执行，不记终身同盟。", "status": "draft", "id": "a15a1933-440e-5f74-9395-2c499059dd0c", "subject_id": "20d178c9-e65b-5e01-81f8-17dc82e2d158", "source_id": "d3357220-e689-5ebf-b1a9-6ec7b921c7de"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱温：以朱全忠名义约攻者。", "citation": "卷258·大顺二年（891）·zztj-v258-y0891-p017·原文件第93行", "note": "原文：硃全忠遣使与杨行密约共攻孙儒。儒恃其兵强，欲先灭行密，后敌全忠，移牒籓镇，数行密、全忠之罪，且曰：“俟平宣、汴，当引兵入朝，除君侧之恶。”于是悉焚扬州庐舍，尽驱丁壮及妇女渡江，杀老弱以充食。行密将张训、李德诚潜入扬州，灭馀火，得谷数十万斛以赈饥民。泗州刺史张谏贷数万斛以给军，训以行密之命馈之，谏由是德行密。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "5231d609-01f4-5ba1-a989-164c1fe2b684", "subject_id": "0555e455-34d4-54ef-b93e-b0e6425018ab", "source_id": "d3357220-e689-5ebf-b1a9-6ec7b921c7de"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱温：以朱全忠名义约攻者。", "citation": "卷258·大顺二年（891）·zztj-v258-y0891-p017·原文件第93行", "note": "原文：硃全忠遣使与杨行密约共攻孙儒。儒恃其兵强，欲先灭行密，后敌全忠，移牒籓镇，数行密、全忠之罪，且曰：“俟平宣、汴，当引兵入朝，除君侧之恶。”